const input = $json.cash_flow_input || {};

const sellingPrice = Number(
  input.selling_price ??
  input.selling_price_per_unit ??
  0
);

const monthlySalesVolume = Number(
  input.monthly_sales_volume ??
  input.monthly_sales ??
  input.sales_volume ??
  0
);

const monthlyRevenue = sellingPrice * monthlySalesVolume;

return [
  {
    json: {
      ...$json,
      revenue_analysis: {
        selling_price_per_unit: sellingPrice,
        monthly_sales_volume: monthlySalesVolume,
        monthly_revenue: monthlyRevenue,
        revenue_status:
          monthlyRevenue > 0
            ? "CALCULATED"
            : "INSUFFICIENT_INFORMATION"
      }
    }
  }
];

const input = $json.cash_flow_input || {};

const purchaseCost = Number(
  input.purchase_cost ??
  input.purchase_cost_per_unit ??
  input.cost_per_unit ??
  0
);

const monthlySalesVolume = Number(
  input.monthly_sales_volume ??
  input.monthly_sales ??
  input.sales_volume ??
  0
);

const monthlyCOGS = purchaseCost * monthlySalesVolume;

return [
  {
    json: {
      ...$json,
      cogs_analysis: {
        purchase_cost_per_unit: purchaseCost,
        monthly_sales_volume: monthlySalesVolume,
        monthly_cogs: monthlyCOGS,
        cogs_status:
          monthlyCOGS > 0
            ? "CALCULATED"
            : "INSUFFICIENT_INFORMATION"
      }
    }
  }
];

const revenue = Number(
  $json.revenue_analysis?.monthly_revenue ?? 0
);

const cogs = Number(
  $json.cogs_analysis?.monthly_cogs ?? 0
);

const grossProfit = revenue - cogs;

const grossMargin =
  revenue > 0
    ? (grossProfit / revenue) * 100
    : null;

return [
  {
    json: {
      ...$json,
      gross_profit_analysis: {
        monthly_revenue: revenue,
        monthly_cogs: cogs,
        monthly_gross_profit: grossProfit,
        gross_margin_percent: grossMargin,
        status:
          revenue > 0 && cogs >= 0
            ? "CALCULATED"
            : "INSUFFICIENT_INFORMATION"
      }
    }
  }
];

const input = $json.cash_flow_input || {};

const operatingExpenses =
  Number(input.monthly_operating_expenses ?? 0);

const grossProfit =
  Number($json.gross_profit_analysis?.monthly_gross_profit ?? 0);

const operatingProfit =
  grossProfit - operatingExpenses;

return [
  {
    json: {
      ...$json,

      operating_expense_analysis: {
        monthly_operating_expenses: operatingExpenses,

        monthly_gross_profit: grossProfit,

        monthly_operating_profit: operatingProfit,

        status:
          operatingExpenses > 0
            ? "CALCULATED"
            : "INSUFFICIENT_INFORMATION"
      }
    }
  }
];

const input = $json.cash_flow_input || {};

const operatingProfit =
  Number($json.operating_expense_analysis?.monthly_operating_profit ?? 0);

const debtPayments =
  Number(input.monthly_debt_payments ?? 0);

const otherCashOutflows =
  Number(input.monthly_other_cash_outflows ?? 0);

const netCashFlow =
  operatingProfit - debtPayments - otherCashOutflows;

return [
  {
    json: {
      ...$json,

      net_cash_flow_analysis: {
        monthly_operating_profit: operatingProfit,
        monthly_debt_payments: debtPayments,
        monthly_other_cash_outflows: otherCashOutflows,
        monthly_net_cash_flow: netCashFlow,

        cash_flow_status:
          netCashFlow > 0
            ? "POSITIVE"
            : netCashFlow < 0
              ? "NEGATIVE"
              : "INSUFFICIENT_INFORMATION"
      }
    }
  }
];

const input = $json.cash_flow_input || {};

const currentCashBalance =
  Number(input.current_cash_balance ?? 0);

const monthlyNetCashFlow =
  Number($json.net_cash_flow_analysis?.monthly_net_cash_flow ?? 0);

let runwayMonths = null;
let runwayStatus = "INSUFFICIENT_INFORMATION";

if (currentCashBalance > 0 && monthlyNetCashFlow < 0) {
  runwayMonths = currentCashBalance / Math.abs(monthlyNetCashFlow);
  runwayStatus = "CALCULATED";
} else if (monthlyNetCashFlow >= 0) {
  runwayStatus = "NO_BURN";
}

return [
  {
    json: {
      ...$json,

      cash_runway_analysis: {
        current_cash_balance: currentCashBalance,
        monthly_net_cash_flow: monthlyNetCashFlow,
        estimated_runway_months: runwayMonths,
        runway_status: runwayStatus
      }
    }
  }
];

const output = $json.text || "";

let cleaned = output
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    "Gemini returned invalid JSON. Raw output: " + output
  );
}

return [
  {
    json: {
      ...$json,
      cash_flow_risk_assessment: parsed
    }
  }
];
